SELECT order_id, order_sent_user_id, order_receive_user_id, order_type, order_amount, order_status, order_timeout, order_view_number, create_time, update_time FROM ch_order WHERE order_is_delete = 0
AND order_receive_user_id = #{userId}
AND order_sent_user_id = #{userId}
AND order_status = #{orderStatus}
ORDER BY create_time DESC, order_id DESC LIMIT #{pageSize}

